INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 100101, "ヒヨリ", 2, "東山奈央", 44, "人助け、応援", "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", "A", 27, 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "獣人族", 8, 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 100201, "ユイ", 2, "種田梨沙", 47, "料理、人間観察", "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", "O", 5, 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "ヒューマン", 4, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 100301, "レイ", 2, "早見沙織", 46, "読書、乗馬、お茶", "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", "B", 12, 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "魔族", 1, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 100401, "ミソギ", 5, "諸星すみれ", 27, "いたずら、探検", "リトルリリカル", "探検好きのイタズラっ子", "O", 10, 9, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "ヒューマン", 8, 128);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 100501, "マツリ", 8, "下田麻美", 40, "ヒーローごっこ", "王宮騎士団（NIGHTMARE）", "ヒーローに憧れる騎士見習いの少女", "O", 25, 12, "？？？", "獣人族", 11, 146);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 100601, "アカリ", 7, "浅倉杏美", 42, "サックス", "悪魔偽王国軍（ディアボロス）", "甘え上手なみんなの人気者", "O", 22, 13, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "魔族", 11, 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 100701, "ミヤコ", 7, "雨宮天", 32, "プリンを食べること", "悪魔偽王国軍（ディアボロス）", "プリン大好きゴースト娘", "B", 23, 14, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "魔族", 1, 130);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 100801, "ユキ", 15, "大空直美", 40, "鏡で自分を見ること", "ヴァイスフリューゲル　ランドソル支部", "ボクは誰よりも美しい", "AB", 10, 14, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "エルフ", 10, 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 100901, "アンナ", 13, "髙野麻美", 45, "小説執筆", "トワイライトキャラバン", "前世を信じる中二病患者、「疾風の冥姫」", "A", 5, 17, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "魔族", 7, 159);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 101001, "マホ", 10, "内田真礼", 42, "空想、ぬいぐるみ集め", "自警団（カォン）", "マホマホ王国のプリンセス", "O", 22, 16, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "獣人族", 9, 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 101101, "リノ", 3, "阿澄佳奈", 44, "お裁縫", "ラビリンス", "人懐っこくてマシンガントークな妹系少女", "A", 25, 15, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "ヒューマン", 8, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 101201, "ハツネ", 6, "大橋彩香", 46, "妹と遊ぶこと、二度寝、昼寝、早寝", "フォレスティエ", "みんなのために超能力を使う眠り姫", "A", 24, 17, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "エルフ", 12, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 101301, "ナナカ", 13, "佳村はるか", 55, "読書、魔法", "トワイライトキャラバン", "オタク全開な魔法少女", "O", 21, 18, "", "魔族", 8, 166);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 101401, "カスミ", 10, "水瀬いのり", 41, "読書、推理", "自警団（カォン）", "頭脳明晰な美少女名探偵", "AB", 3, 15, "test", "獣人族", 11, 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 101501, "ミサト", 6, "國府田マリ子", 54, "絵本作り", "フォレスティエ", "母性溢れる優しいみんなの「ミサト先生」", "O", 5, 21, "test", "エルフ", 9, 165);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 101601, "スズナ", 14, "上坂すみれ", 48, "ファッション", "ルーセント学院", "天真爛漫で人気者のカリスマモデル", "O", 10, 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "魔族", 4, 167);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 101701, "カオリ", 10, "高森奈津美", 53, "踊り、空手", "自警団（カォン）", "いつでも「なんくるないさ～」な天然娘", "A", 7, 17, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "獣人族", 7, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 101801, "イオ", 14, "伊藤静", 52, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "ルーセント学院", "多くの男性を魅了する無垢な女教師", "B", 14, 23, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "魔族", 8, 162);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 102001, "ミミ", 5, "日高里菜", 21, "かわいいもの集め", "リトルリリカル", "お歌もにんじんも、ウサギさんも大好き♪", "O", 3, 10, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "獣人族", 4, 117);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 102101, "クルミ", 9, "植田佳奈", 40, "観劇、おままごと", "サレンディア救護院", "泣き虫で臆病な守ってあげたい女の子", "B", 9, 12, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "ヒューマン", 6, 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 102201, "ヨリ", 7, "原紗友里", 40, "ゲーム全般", "悪魔偽王国軍（ディアボロス）", "人見知りであまのじゃくな女の子", "O", 22, 13, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "魔族", 11, 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 102301, "アヤネ", 9, "芹澤優", 38, "屋内でできる遊び", "サレンディア救護院", "ぷうきちといつも一緒！", "B", 10, 14, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ヒューマン", 5, 148);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 102501, "スズメ", 9, "悠木碧", 43, "ご奉仕", "サレンディア救護院", "お嬢さまのためにがんばるドジっ娘メイド", "O", 12, 15, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "ヒューマン", 12, 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 102601, "リン", 11, "小岩井ことり", 42, "あんパン", "牧場（エリザベスパーク）", "遊びと睡眠が何より大事なぐうたら娘", "B", 1, 17, "test", "獣人族", 1, 144);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 102701, "エリコ", 13, "橋本ちなみ", 43, "実験、裁縫、料理", "トワイライトキャラバン", "運命の相手に一途すぎる乙女", "B", 30, 16, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "魔族", 7, 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 102801, "サレン", 9, "堀江由衣", 43, "経営、お茶会", "サレンディア救護院", "救護院を経営する優しい庶民派お嬢様", "A", 4, 17, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "エルフ", 10, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 102901, "ノゾミ", 4, "日笠陽子", 40, "舞台鑑賞、ダンス", "カルミナ", "歌って踊れる大人気アイドル", "B", 24, 17, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "ヒューマン", 1, 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 103001, "ニノン", 15, "佐藤聡美", 51, "忍法開発", "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", "O", 31, 16, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "ヒューマン", 8, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 103101, "シノブ", 7, "大坪由佳", 42, "占い", "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", "AB", 22, 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "魔族", 12, 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 103201, "アキノ", 12, "松嵜麗", 45, "慈善事業", "メルクリウス財団", "一人前の商人を目指すパワフルお嬢様", "AB", 12, 18, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "ヒューマン", 3, 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 103301, "マヒル", 11, "新田恵海", 35, "漫才", "牧場（エリザベスパーク）", "みんなを笑顔にするお笑い牧場主", "B", 3, 20, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "ヒューマン", 3, 142);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 103401, "ユカリ", 12, "今井麻美", 55, "ウインドーショッピング", "メルクリウス財団", "純情でほっとけない大人の女性", "A", 16, 22, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "エルフ", 3, 164);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 103601, "キョウカ", 5, "小倉唯", 21, "お勉強", "リトルリリカル", "礼儀正しくしっかり者のちびっ子優等生", "A", 2, 8, "test", "エルフ", 2, 118);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 103701, "トモ", 8, "茅原実里", 43, "剣術、年長者をからかう", "王宮騎士団（NIGHTMARE）", "義理堅くてからかい好きな剣術少女", "A", 11, 13, "test", "ヒューマン", 8, 149);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 103801, "シオリ", 11, "小清水亜美", 40, "読書、お散歩", "牧場（エリザベスパーク）", "読書が趣味の病弱少女", "A", 3, 14, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "獣人族", 11, 153);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 104001, "アオイ", 6, "花澤香菜", 44, "友達作りのイメトレ", "フォレスティエ", "「友達」に憧れる、エルフの森の女の子", "AB", 6, 13, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "エルフ", 6, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 104201, "チカ", 4, "福原綾香", 46, "各種楽器", "カルミナ", "人々を守るために歌う、唱喚士の少女", "O", 3, 17, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "ヒューマン", 6, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 104301, "マコト", 10, "小松未可子", 54, "お菓子作り", "自警団（カォン）", "男勝りで情に厚いワイルド娘", "O", 9, 17, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "獣人族", 8, 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 104401, "イリヤ", 7, "丹下桜", 50, "世界征服", "悪魔偽王国軍（ディアボロス）", "かつては夜を支配した最強の吸血鬼", "A", 5, "??", "test", "魔族", 5, 172);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 104501, "クウカ", 15, "長妻樹里", 49, "小説を読むこと", "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", "AB", 19, 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "ヒューマン", 11, 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 104601, "タマキ", 12, "沼倉愛美", 48, "猫とたわむれること", "メルクリウス財団", "弱きを助け強きをくじく猫娘", "AB", 1, 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "獣人族", 3, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 104701, "ジュン", 8, "川澄綾子", 50, "格闘技、湯浴み", "王宮騎士団（NIGHTMARE）", "素顔を見せない冷静沈着な女性騎士", "A", 25, 25, "？？？", "ヒューマン", 10, 171);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 104801, "ミフユ", 12, "田所あずさ", 49, "傭兵などのアルバイト", "メルクリウス財団", "仕事も私事も効率優先な傭兵少女", "O", 11, 20, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "ヒューマン", 11, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 104901, "シズル", 3, "生天目仁美", 54, "家事全般", "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", "O", 24, 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ヒューマン", 10, 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105001, "ミサキ", 14, "久野美咲", 22, "ファッション誌鑑賞、コスメ集め", "ルーセント学院", "ちょっとおませな恋に恋する女の子", "A", 3, 11, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "魔族", 1, 120);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105101, "ミツキ", 13, "三石琴乃", 53, "研究、実験", "トワイライトキャラバン", "実験が趣味の危険な科学者", "A", 7, 27, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "ヒューマン", 3, 166);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105201, "リマ", 11, "徳井青空", 100, "毛繕い、お喋り", "牧場（エリザベスパーク）", "乙女チックなもふもふアニマル", "A", 14, 17, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "獣人族", 3, 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105301, "モニカ", 15, "辻あゆみ", 33, "お菓子屋通い", "ヴァイスフリューゲル　ランドソル支部", "見た目も中身もお子ちゃまな異国の軍人", "A", 28, 17, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "ヒューマン", 7, 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105401, "ツムギ", 4, "木戸衣吹", 45, "裁縫", "カルミナ", "ファッション大好きなキュートガール", "AB", 7, 14, "test", "ヒューマン", 9, 153);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105501, "アユミ", 15, "大関英里", 43, "観察", "ヴァイスフリューゲル　ランドソル支部", "どこまでも一途に慕う、純情乙女", "O", 7, 16, "test", "エルフ", 4, 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105601, "ルカ", 13, "佐藤利奈", 54, "釣り", "トワイライトキャラバン", "人情味溢れる粋でいなせな「姉御」", "B", 11, 25, "test", "ヒューマン", 7, 167);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105701, "ジータ", "", "金元寿子", 45, "冒険、おしゃべり", "？？？", "空への冒険を夢見る騎空士の少女", "O", 10, 17, "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "ヒューマン", 3, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105801, "ペコリーヌ", 1, "M・A・O", 46, "食べ歩き、料理", "美食殿", "いつも元気な腹ペコ少女", "O", 31, 17, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "ヒューマン", 3, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 105901, "コッコロ", 1, "伊藤美来", 35, "瞑想、動植物の飼育", "美食殿", "主を慕う、小さなガイド役", "B", 11, 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "エルフ", 5, 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 106001, "キャル", 1, "立花理香", 39, "猫と遊ぶ", "美食殿", "行き倒れの謎のネコミミ魔法使い", "A", 2, 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "獣人族", 9, 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 106101, "ムイミ", "", "潘めぐみ", 40, "冒険、思い出話", "？？？", "さまよえる謎の少女", "O", 11, 16, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "ヒューマン", 8, 148);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 106301, "アリサ", "", "優木かな", 42, "キレイな葉っぱを集めること", "？？？", "森番を目指すエルフの少女", "O", 17, 15, "", "エルフ", 6, 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 106401, "シェフィ", 1, "近藤玲奈", "???", "読書、ストレッチ", "美食殿", "記憶喪失のドラゴン娘", "B", 14, 14, "", "ドラゴン族", 12, 147);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 106501, "カヤ", 17, "小市眞琴", "???", "格闘技", "ドラゴンズネスト", "拳で語る喧嘩屋ドラゴン少女", "B", 25, 16, "", "ドラゴン族", 6, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 106601, "イノリ", 17, "藤田茜", "???", "ゲーム", "ドラゴンズネスト", "口が達者なヘタレドラゴン", "AB", 29, 13, "", "ドラゴン族", 9, 145);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 106701, "ホマレ", 17, "大西沙織", "???", "絵画、読書", "ドラゴンズネスト", "妖しい微笑で全てを見透かす臥竜の頭領", "O", 17, 25, "", "ドラゴン族", 4, 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 106801, "ラビリスタ", 3, "沢城みゆき", "??", "人間観察", "ラビリンス", "秘密結社ラビリンスの『迷宮女王』", "AB", 25, 25, "", "ヒューマン", 7, 160);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 106901, "カイザーインサイト", "", "蒼井翔太", "??", "占い、支配", "？？？", "謎に包まれたランドソルの主", "AB", 1, 29, "", "獣人族", 7, 166);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 107001, "ネネカ", "", "井口裕香", "??", "物真似、芸術鑑賞", "？？？", "研究所に隠れ住む物静かなお姉さん", "O", 24, 24, "", "エルフ", 3, 149);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 107101, "クリスティーナ", 8, "たかはし智秋", "??", "強敵との闘争", "王宮騎士団（NIGHTMARE）", "傍若無人な王宮騎士団副団長", "O", 7, 27, "", "ヒューマン", 2, 165);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 107501, "ペコリーヌ（サマー）", 1, "M・A・O", 46, "食べ歩き、料理", "美食殿", "いつも元気な腹ペコ少女", "O", 31, 17, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "ヒューマン", 3, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 107601, "コッコロ（サマー）", 1, "伊藤美来", 35, "瞑想、動植物の飼育", "美食殿", "主を慕う、小さなガイド役", "B", 11, 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "エルフ", 5, 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 107701, "スズメ（サマー）", 9, "悠木碧", 43, "ご奉仕", "サレンディア救護院", "お嬢さまのためにがんばるドジっ娘メイド", "O", 12, 15, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "ヒューマン", 12, 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 107801, "キャル（サマー）", 1, "立花理香", 39, "猫と遊ぶ", "美食殿", "行き倒れの謎のネコミミ魔法使い", "A", 2, 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "獣人族", 9, 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 107901, "タマキ（サマー）", 12, "沼倉愛美", 48, "猫とたわむれること", "メルクリウス財団", "弱きを助け強きをくじく猫娘", "AB", 1, 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "獣人族", 3, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108001, "ミフユ（サマー）", 12, "田所あずさ", 49, "傭兵などのアルバイト", "メルクリウス財団", "仕事も私事も効率優先な傭兵少女", "O", 11, 20, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "ヒューマン", 11, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108101, "シノブ（ハロウィン）", 7, "大坪由佳", 42, "占い", "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", "AB", 22, 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "魔族", 12, 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108201, "ミヤコ（ハロウィン）", 7, "雨宮天", 32, "プリンを食べること", "悪魔偽王国軍（ディアボロス）", "プリン大好きゴースト娘", "B", 23, 14, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "魔族", 1, 130);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108301, "ミサキ（ハロウィン）", 14, "久野美咲", 22, "ファッション誌鑑賞、コスメ集め", "ルーセント学院", "ちょっとおませな恋に恋する女の子", "A", 3, 11, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "魔族", 1, 120);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108401, "チカ（クリスマス）", 4, "福原綾香", 46, "各種楽器", "カルミナ", "人々を守るために歌う、唱喚士の少女", "O", 3, 17, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "ヒューマン", 6, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108501, "クルミ（クリスマス）", 9, "植田佳奈", 40, "観劇、おままごと", "サレンディア救護院", "泣き虫で臆病な守ってあげたい女の子", "B", 9, 12, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "ヒューマン", 6, 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108601, "アヤネ（クリスマス）", 9, "芹澤優", 38, "屋内でできる遊び", "サレンディア救護院", "ぷうきちといつも一緒！", "B", 10, 14, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ヒューマン", 5, 148);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108701, "ヒヨリ（ニューイヤー）", 2, "東山奈央", 44, "人助け、応援", "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", "A", 27, 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "獣人族", 8, 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108801, "ユイ（ニューイヤー）", 2, "種田梨沙", 47, "料理、人間観察", "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", "O", 5, 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "ヒューマン", 4, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 108901, "レイ（ニューイヤー）", 2, "早見沙織", 46, "読書、乗馬、お茶", "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", "B", 12, 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "魔族", 1, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 109001, "エリコ（バレンタイン）", 13, "橋本ちなみ", 43, "実験、裁縫、料理", "トワイライトキャラバン", "運命の相手に一途すぎる乙女", "B", 30, 16, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "魔族", 7, 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 109101, "シズル（バレンタイン）", 3, "生天目仁美", 54, "家事全般", "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", "O", 24, 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ヒューマン", 10, 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 109201, "アン", "", "日笠陽子", 55, "読書", "？？？", "英霊と契約を結んだマナリアの天才王女", "AB", 1, 17, "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "ヒューマン", 12, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 109301, "ルゥ", "", "こやまきみこ", 45, "食べること、眠ること", "？？？", "マナリア魔法学院の新入生", "O", 4, 16, "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "ヒューマン", 2, 144);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 109401, "グレア", "", "福原綾香", 67, "ピアノ", "？？？", "人を超越した力を有す心優しい竜姫", "B", 3, 17, "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "半人半竜", 11, 167);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 109501, "クウカ（オーエド）", 15, "長妻樹里", 49, "小説を読むこと", "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", "AB", 19, 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "ヒューマン", 11, 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 109601, "ニノン（オーエド）", 15, "佐藤聡美", 51, "忍法開発", "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", "O", 31, 16, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "ヒューマン", 8, 163);
