INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 114001, "レイ（ハロウィン）", 2, "早見沙織", 46, "読書、乗馬、お茶", "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", "B", 12, 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "魔族", 1, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 114101, "マツリ（ハロウィン）", 8, "下田麻美", 40, "ヒーローごっこ", "王宮騎士団（NIGHTMARE）", "ヒーローに憧れる騎士見習いの少女", "O", 25, 12, "", "獣人族", 11, 146);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 114201, "モニカ（マジカル）", 15, "辻あゆみ", 33, "お菓子屋通い", "ヴァイスフリューゲル　ランドソル支部", "見た目も中身もお子ちゃまな異国の軍人", "A", 28, 17, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "ヒューマン", 7, 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 114301, "トモ（マジカル）", 8, "茅原実里", 43, "剣術、年長者をからかう", "王宮騎士団（NIGHTMARE）", "義理堅くてからかい好きな剣術少女", "A", 11, 13, "", "ヒューマン", 8, 149);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 114401, "アキノ（クリスマス）", 12, "松嵜麗", 45, "慈善事業", "メルクリウス財団", "一人前の商人を目指すパワフルお嬢様", "AB", 12, 18, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "ヒューマン", 3, 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 114501, "サレン（クリスマス）", 9, "堀江由衣", 43, "経営、お茶会", "サレンディア救護院", "救護院を経営する優しい庶民派お嬢様", "A", 4, 17, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "エルフ", 10, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 114601, "ユカリ（クリスマス）", 12, "今井麻美", 55, "ウインドーショッピング", "メルクリウス財団", "純情でほっとけない大人の女性", "A", 16, 22, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "エルフ", 3, 164);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 114701, "ムイミ（ニューイヤー）", "", "潘めぐみ", 40, "冒険、思い出話", "？？？", "さまよえる謎の少女", "O", 11, 16, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "ヒューマン", 8, 148);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 115001, "ネネカ（ニューイヤー）", "", "井口裕香", "??", "物真似、芸術鑑賞", "？？？", "研究所に隠れ住む物静かなお姉さん", "O", 24, 24, "", "エルフ", 3, 149);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 115501, "コッコロ（儀装束）", 1, "伊藤美来", 35, "瞑想、動植物の飼育", "美食殿", "主を慕う、小さなガイド役", "B", 11, 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "エルフ", 5, 140);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 115601, "ユイ（儀装束）", 2, "種田梨沙", 47, "料理、人間観察", "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", "O", 5, 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "ヒューマン", 4, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 115701, "カスミ（サマー）", 10, "水瀬いのり", 41, "読書、推理", "自警団（カォン）", "頭脳明晰な美少女名探偵", "AB", 3, 15, "", "獣人族", 11, 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 115801, "リマ（シンデレラ）", 11, "徳井青空", 100, "毛繕い、お喋り", "牧場（エリザベスパーク）", "乙女チックなもふもふアニマル", "A", 14, 17, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "獣人族", 3, 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 115901, "マコト（シンデレラ）", 10, "小松未可子", 54, "お菓子作り", "自警団（カォン）", "男勝りで情に厚いワイルド娘", "O", 9, 17, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "獣人族", 8, 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 116001, "マホ（シンデレラ）", 10, "内田真礼", 42, "空想、ぬいぐるみ集め", "自警団（カォン）", "マホマホ王国のプリンセス", "O", 22, 16, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "獣人族", 9, 155);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 116201, "クロエ（聖学祭）", 16, "種﨑敦美", 42, "ダーツ", "聖テレサ女学院（なかよし部）", "ダウンタウン育ちのダウナー系エルフ", "O", 7, 17, "", "エルフ", 8, 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 116301, "チエル（聖学祭）", 16, "佐倉綾音", 46, "ダンス、カラオケ", "聖テレサ女学院（なかよし部）", "自由奔放ナチュラル無礼な現代っ子", "O", 15, 16, "", "ヒューマン", 9, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 116401, "ユニ（聖学祭）", 16, "小原好美", 36, "読書", "聖テレサ女学院（なかよし部）", "書庫に眠れる小さな賢人", "O", 28, 18, "", "ヒューマン", 2, 142);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 116501, "イノリ（タイムトラベル）", 17, "藤田茜", "???", "ゲーム", "ドラゴンズネスト", "口が達者なヘタレドラゴン", "AB", 29, 13, "", "ドラゴン族", 9, 145);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 116601, "カヤ（タイムトラベル）", 17, "小市眞琴", "???", "格闘技", "ドラゴンズネスト", "拳で語る喧嘩屋ドラゴン少女", "B", 25, 16, "", "ドラゴン族", 6, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 116701, "アオイ（作業服）", 6, "花澤香菜", 44, "友達作りのイメトレ", "フォレスティエ", "「友達」に憧れる、エルフの森の女の子", "AB", 6, 13, "", "エルフ", 6, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 116801, "タマキ（作業服）", 12, "沼倉愛美", 48, "猫とたわむれること", "メルクリウス財団", "弱きを助け強きをくじく猫娘", "AB", 1, 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "獣人族", 3, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 116901, "ミフユ（作業服）", 12, "田所あずさ", 49, "傭兵などのアルバイト", "メルクリウス財団", "仕事も私事も効率優先な傭兵少女", "O", 11, 20, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "ヒューマン", 11, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117001, "エリコ（サマー）", 13, "橋本ちなみ", 43, "実験、裁縫、料理", "トワイライトキャラバン", "運命の相手に一途すぎる乙女", "B", 30, 16, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "魔族", 7, 154);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117101, "シズル（サマー）", 3, "生天目仁美", 54, "家事全般", "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", "O", 24, 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ヒューマン", 10, 168);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117201, "ノゾミ（サマー）", 4, "日笠陽子", 40, "舞台鑑賞、ダンス", "カルミナ", "歌って踊れる大人気アイドル", "B", 24, 17, "", "ヒューマン", 1, 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117301, "チカ（サマー）", 4, "福原綾香", 46, "各種楽器", "カルミナ", "人々を守るために歌う、唱喚士の少女", "O", 3, 17, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "ヒューマン", 6, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117401, "ツムギ（サマー）", 4, "木戸衣吹", 45, "裁縫", "カルミナ", "ファッション大好きなキュートガール", "AB", 7, 14, "", "ヒューマン", 9, 153);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117501, "ミツキ（オーエド）", 13, "三石琴乃", 53, "研究、実験", "トワイライトキャラバン", "実験が趣味の危険な科学者", "A", 7, 27, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "ヒューマン", 3, 166);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117601, "ユキ（オーエド）", 15, "大空直美", 40, "鏡で自分を見ること", "ヴァイスフリューゲル　ランドソル支部", "ボクは誰よりも美しい", "AB", 10, 14, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "エルフ", 10, 150);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117701, "カオリ（ハロウィン）", 10, "高森奈津美", 53, "踊り、空手", "自警団（カォン）", "いつでも「なんくるないさ～」な天然娘", "A", 7, 17, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "獣人族", 7, 158);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117801, "ニノン（ハロウィン）", 15, "佐藤聡美", 51, "忍法開発", "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", "O", 31, 16, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "ヒューマン", 8, 163);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 117901, "スズナ（ハロウィン）", 14, "上坂すみれ", 48, "ファッション", "ルーセント学院", "天真爛漫で人気者のカリスマモデル", "O", 10, 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "魔族", 4, 167);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 118001, "クレジッタ", 18, "Lynn", 57, "お金を数えること、悪だくみ", "リッチモンド商工会", "忠義に目覚めた女商人", "A", 19, 26, "", "ヒューマン", 9, 160);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 118101, "ランファ", 19, "原田彩楓", 53, "歌、読書、詩を書くこと", "レイジ・レギオン", "静寂を求め歌う陰気少女", "O", 28, 20, "", "魔族", 12, 165);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 118201, "ミソラ", 19, "鬼頭明里", "??", "特に無し", "レイジ・レギオン", "明朗快活、なれど破滅に流るる溌溂少女", "A", 2, 16, "", "ヒューマン", 7, 159);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 118501, "カリン", "", "洲崎綾", 43, "書類仕事、散歩、ボードゲーム", "？？？", "【ギルド管理協会】職員の親切なお姉さん", "A", 12, 24, "", "ヒューマン", 9, 152);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 118601, "ネビア", "", "相坂優歌", "???", "悪戯をすること", "？？？", "幻霧に戯れる悪戯好きなガイド妖精", "?", "?", "??", "", "？？？", "?", "???");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 119001, "イオ（ノワール）", 14, "伊藤静", 52, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "ルーセント学院", "多くの男性を魅了する無垢な女教師", "B", 14, 23, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "魔族", 8, 162);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 119101, "クウカ（ノワール）", 15, "長妻樹里", 49, "小説を読むこと", "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", "AB", 19, 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "ヒューマン", 11, 157);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 119201, "マヒル（クリスマス）", 11, "新田恵海", 35, "漫才", "牧場（エリザベスパーク）", "みんなを笑顔にするお笑い牧場主", "B", 3, 20, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "ヒューマン", 3, 142);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 119301, "リノ（クリスマス）", 3, "阿澄佳奈", 44, "お裁縫", "ラビリンス", "人懐っこくてマシンガントークな妹系少女", "A", 25, 15, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "ヒューマン", 8, 156);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 119901, "ミヤコ（クリスマス）", 7, "雨宮天", 32, "プリンを食べること", "悪魔偽王国軍（ディアボロス）", "プリン大好きゴースト娘", "B", 23, 14, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "魔族", 1, 130);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 120001, "シズル（ノワール）", 3, "生天目仁美", 54, "家事全般", "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", "O", 24, 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ヒューマン", 10, 168);
