INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 121901, "アンナ（パイレーツ）", 13, "髙野麻美", 45, "小説執筆", "トワイライトキャラバン", "前世を信じる中二病患者、「疾風の冥姫」", "A", 5, 17, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "魔族", 7, 159);
