INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 122401, "ヒヨリ（サマー）", 2, "東山奈央", 44, "人助け、応援", "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", "A", 27, 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "獣人族", 8, 155);
