INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (0, 125101, "タマキ（カフェ）", 12, "沼倉愛美", 48, "猫とたわむれること", "メルクリウス財団", "弱きを助け強きをくじく猫娘", "AB", 1, 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "獣人族", 3, 158);
